update sys_wechat_session
display_name = #{displayName}, is_group = #{isGroup}, self_username = #{selfUsername}, self_labels = #{selfLabels}, target_labels = #{targetLabels}, identity_confirmed = #{identityConfirmed}, synced_until = #{syncedUntil}, last_sync_time = #{lastSyncTime}, affinity_score = #{affinityScore}, acquaintance_date = #{acquaintanceDate}, my_performance_score = #{myPerformanceScore}, next_step_suggestion = #{nextStepSuggestion}, update_by = #{updateBy}, remark = #{remark}, update_time = sysdate()
where session_id = #{sessionId}

update sys_wechat_session s
set s.msg_count = (
        select count(*) from sys_wechat_message m
        where m.session_id = s.session_id and m.del_flag = '0'
    ),
    s.unanalyzed_count = (
        select count(*) from sys_wechat_message m
        where m.session_id = s.session_id and m.del_flag = '0' and m.analyzed = '0'
    )
where s.session_id = #{sessionId}

update sys_wechat_session set del_flag = '2'
where user_id = #{userId} and session_id in

    #{sessionId}
